{
  "name": "@audaxic/memory-opencode",
  "version": "1.2.1",
  "type": "module",
  "description": "OpenCode plugin for Audaxic Memory - automatically saves conversation facts to your persistent memory layer",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    "./server": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "bin": {
    "audaxic-setup": "./bin/setup.js"
  },
  "files": [
    "dist",
    "bin"
  ],
  "scripts": {
    "build": "tsc && bun build src/tui.tsx --outdir dist --target bun --external @opentui/solid --external @opentui/core --external @opentui/keymap --external solid-js",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "audaxic",
    "ai",
    "context",
    "conversation"
  ],
  "author": "Audaxic",
  "license": "MIT",
  "homepage": "https://memory.audaxic.com",
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": ">=0.4.5"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@opencode-ai/sdk": "latest",
    "@opentui/solid": "0.4.5",
    "@types/node": "^26.1.2",
    "typescript": "^5.5.0"
  }
}
